def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 1:
        if opp_last == 'C':
            return 'C'
        return 'D'

    prev_my, prev_opp = history[-2]

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1

    recent_c = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_c += 1

    d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        d_streak += 1
        i -= 1

    if opp_last == 'C':
        if my_last == 'D':
            return 'D'
        if n < 90 and recent_c >= 5 and rng.random() < 0.04:
            return 'D'
        return 'C'

    if my_last == 'D':
        if prev_my == 'C' and prev_opp == 'D':
            if opp_c * 100 > n * 50 and rng.random() < 0.03:
                return 'C'
            return 'D'

        if opp_c == 0:
            if n <= 7 and d_streak >= 3 and d_streak <= 5 and rng.random() < 0.06:
                return 'C'
            return 'D'

        if prev_opp == 'C':
            return 'C'

        if opp_c * 100 > n * 68:
            return 'C'

        if recent_c >= 3 and d_streak >= 4 and rng.random() < 0.12:
            return 'C'

        if opp_c * 100 > n * 45 and rng.random() < 0.04:
            return 'C'

        return 'D'

    if prev_my == 'D' and prev_opp == 'D':
        if n >= 3 and history[-3][0] == 'C' and history[-3][1] == 'D':
            return 'D'
        if opp_c == 0 and n > 8:
            return 'D'
        return 'C'

    if prev_my == 'C' and prev_opp == 'D':
        return 'D'

    if prev_opp == 'C' and opp_c * 100 > n * 85 and rng.random() < 0.45:
        return 'C'

    return 'D'
